    "_{counted} post, all of them_::_{counted} posts, all of them_" : ["Objava {counted}, vsi", "Vse objave {counted}", "Vse objave {counted}", "Vse objave {counted}"],
    "Estimated reach" : "Ocenjeni doseg",
