    "_Counted over your one post._::_Counted over all {count} of your posts._" : ["Preštel sem tvojo eno objavo.", "Šteje se za vse vaše objave {count}.", "Šteje se za vse vaše objave {count}.", "Šteje se za vse vaše objave {count}."],
